SELECT COUNT(*) AS refund_rows, COUNT(o.order_id) AS joined_order_rows FROM public.refunds r LEFT JOIN public.orders o ON o.order_id = r.order_id;
SELECT COUNT(*) AS orders_with_multiple_refund_rows FROM (SELECT order_id FROM public.refunds GROUP BY order_id HAVING COUNT(*) > 1) x;
SELECT customer_name, customer_id FROM public.customers ORDER BY customer_id;

